<template>
  <div id="booking">
    <v-carousel height="100vh" hide-controls dark hide-delimiters class="myCarousel">
      <v-carousel-item
        v-for="(item,i) in carouselitems"
        :key="i"
        :src="item.src"
        class="carouselItem"
      ></v-carousel-item>
      <v-jumbotron dark class="myJumbotron">
        <v-container fill-height>
          <v-layout align-center>
            <v-flex class="showcaseText">
              <h2
                class="text-lg-center text-md-center text-xs-center myHeading wow fadeInUp"
              >Booking</h2>
              <p
                class="subheading text-lg-center text-md-center text-xs-center mygreenText wow fadeInRight"
              >Hospitality Unparalled</p>
            </v-flex>
          </v-layout>
        </v-container>
      </v-jumbotron>
    </v-carousel>
    <v-layout class="section" row wrap>
      <v-flex lg12 md12 sm12 xs12>
        <v-card class="form-card" justify-center>
          <v-alert v-if="alert2" :value="true" class="myalert2" type="success">Booking sent</v-alert>

          <v-card-text
            class="display-2 mybrownText text-lg-center text-md-center text-sm-center text-xs-center"
          >Book with us</v-card-text>
          <v-form class="form-body" ref="booking" v-model="bvalid">
            <v-text-field
              class="text-field"
              color="green"
              v-model="bname"
              :rules="nameRules"
              :counter="30"
              label="Name"
              required
            ></v-text-field>
            <v-text-field
              class="text-field"
              color="green"
              v-model="bnumber"
              :counter="10"
              label="Phone Number"
              required
            ></v-text-field>
            <v-text-field
              class="text-field"
              color="green"
              v-model="bemail"
              :counter="50"
              :rules="emailRules"
              label="E-mail"
              required
            ></v-text-field>
            <v-layout row wrap>
              <v-flex lg8>
                <v-select
                  v-model="accomodation"
                  :items="Accomodation"
                  color="green"
                  label="Accomodations"
                ></v-select>
              </v-flex>
              <v-flex lg4>
                <v-text-field
                  class="text-field pl-2"
                  v-model="accnumber"
                  color="green"
                  label="Number of people"
                  required
                ></v-text-field>
              </v-flex>
            </v-layout>
            <v-layout row wrap>
              <v-flex lg8>
                <v-select
                  v-model="conference"
                  :items="Conferences"
                  color="green"
                  label="Conference"
                ></v-select>
              </v-flex>
              <v-flex lg4>
                <v-text-field
                  class="text-field pl-2"
                  v-model="confnumber"
                  color="green"
                  label="Number of people"
                  required
                ></v-text-field>
              </v-flex>
            </v-layout>
            <v-layout row wrap>
              <v-flex xs12 sm6 md4>
                <v-dialog
                  ref="dialog"
                  v-model="modal"
                  :return-value.sync="date"
                  persistent
                  lazy
                  full-width
                  width="290px"
                >
                  <template v-slot:activator="{ on }">
                    <v-text-field
                      v-model="date"
                      label="Arrival Date"
                      color="green"
                      prepend-icon="event"
                      readonly
                      v-on="on"
                    ></v-text-field>
                  </template>
                  <v-date-picker v-model="date" scrollable>
                    <v-spacer></v-spacer>
                    <v-btn flat color="brown" @click="modal = false">Cancel</v-btn>
                    <v-btn flat color="green" @click="$refs.dialog.save(date)">OK</v-btn>
                  </v-date-picker>
                </v-dialog>
              </v-flex>
              <v-spacer></v-spacer>
              <v-flex xs12 sm6 md4></v-flex>
              <v-flex xs12 sm6 md4>
                <v-dialog
                  ref="dialog2"
                  v-model="modal2"
                  :return-value.sync="date"
                  color="green"
                  persistent
                  lazy
                  full-width
                  width="290px"
                >
                  <template v-slot:activator="{ on }">
                    <v-text-field
                      v-model="deptdate"
                      label="Departure Date"
                      prepend-icon="event"
                      color="green"
                      readonly
                      v-on="on"
                    ></v-text-field>
                  </template>
                  <v-date-picker v-model="deptdate" scrollable>
                    <v-spacer></v-spacer>
                    <v-btn flat color="brown" @click="modal2 = false">Cancel</v-btn>
                    <v-btn flat color="green" @click="$refs.dialog2.save(deptdate)">OK</v-btn>
                  </v-date-picker>
                </v-dialog>
              </v-flex>
              <v-spacer></v-spacer>
            </v-layout>
            <v-layout row wrap justify-space-around>
              <v-btn color="#2cc804" :disabled="!bvalid" @click="submit">submit</v-btn>
            </v-layout>
          </v-form>
        </v-card>
      </v-flex>
      <v-flex lg12 md12 sm12 xs12>
        <v-layout row wrap>
          <v-flex lg6>
            <div class="imageGrid">
              <v-container fluid>
                <div class="mapouter">
                  <div class="gmap_canvas">
                    <iframe
                      width="600"
                      height="500"
                      id="gmap_canvas"
                      src="https://maps.google.com/maps?q=fort%20hotel%20mami&t=&z=13&ie=UTF8&iwloc=&output=embed"
                      frameborder="0"
                      scrolling="no"
                      marginheight="0"
                      marginwidth="0"
                    ></iframe>Google Maps Generator by
                    <a
                      href="https://www.embedgooglemap.net"
                    >embedgooglemap.net</a>
                  </div>
                </div>
              </v-container>
            </div>
          </v-flex>
          <v-flex lg6>
            <div class="myfootertext textPosition">
              <h3 class="mybrowntext">Where to find us</h3>
              <p
                class="mybrownText"
              >The facility is located Approx. 50 meters from the Junction Mall, Family Bank branch, off Wote/Makindu road</p>
              <h3 class="mybrowntext">Contact us</h3>
              <p class="mybrownText">Tel: 0 412 244 000 213 | 0743518086</p>
              <p class="mybrownText">Email: forthotel@gmail.com</p>
              <p class="mybrownText">P.O Box 387-90300</p>
            </div>
          </v-flex>
        </v-layout>
      </v-flex>
    </v-layout>
  </div>
</template>
<script>
import { APIService } from "../Api";
const apiService = new APIService();

export default {
  name: "Booking",
  data: () => ({
    bvaild: false,
    bname: "",
    bnumber: "",
    bemail: "",
    alert2: false,
    accomodation: null,
    conference: null,
    accnumber: "0",
    confnumber: "0",
    Accomodation: [
      "Single Room",
      "Deluxe Rooms",
      "Family Rooms",
      "Suite",
      "None"
    ],
    Conferences: ["Mami BoardRoom", "Baraza Hall", "None"],
    modal: false,
    modal2: false,
    date: new Date().toISOString().substr(0, 10),
    deptdate: new Date().toISOString().substr(0, 10),
    nameRules: [
      v => !!v || "Name is required",
      v => v.length <= 10 || "Name must be less than 10 characters"
    ],
    emailRules: [
      v => !!v || "E-mail is required",
      v => /.+@.+/.test(v) || "E-mail must be valid"
    ],
    carouselitems: [
      {
        src: require("../assets/images/grounds/imageY.jpg")
      },
      {
        src: require("../assets/images/grounds/imageG.jpg")
      },
      {
        src: require("../assets/images/grounds/imageO.jpg")
      }
    ]
  }),
  methods: {
    submit() {
      let mail_subject = "Booking Information";
      let mail_body =
        "<p>" +
        " Name: " +
        this.bname +
        "</p>" +
        "<p>" +
        " Email: " +
        this.bemail +
        "</p>" +
        "<p>" +
        " Number: " +
        this.bnumber +
        "</p>" +
        "<p>" +
        " Accomodation: " +
        this.accomodation +
        "</p>" +
        "<p>" +
        " Conference: " +
        this.conference +
        "</p>" +
        "<p>" +
        " Number of people accomodation: " +
        this.accnumber +
        "</p>" +
        "<p>" +
        " Number of people conference: " +
        this.confnumber +
        "</p>" +
        "<p>" +
        " Arrival Date: " +
        this.date +
        "</p>" +
        "<p>" +
        " Departure Date: " +
        this.deptdate +
        "</p>";
      apiService.sendFormData(mail_subject, mail_body);
      this.$refs.booking.reset();
      this.alert2 = true;
    }
  }
};
</script>
<style>
@import "../assets/css/style.css";
.myalert2 {
  position: fixed;
  top: 0;
  width: 100%;
}
.form-card {
  margin: 2em auto 1em;
  width: 60vw;
}
.form-body {
  width: 60%;
  margin: 1em auto;
}

.mapouter {
  position: relative;
  text-align: right;
  height: 500px;
  width: 600px;
}
.gmap_canvas {
  overflow: hidden;
  background: none !important;
  height: 500px;
  width: 600px;
}
.myfootertext {
  padding-left: 3.5em;
}
@media screen and (max-width: 960px) {
  .mapouter {
    position: relative;
    text-align: right;
    height: 500px;
    width: 80vw;
  }
  .gmap_canvas {
    overflow: hidden;
    background: none !important;
    height: 500px;
    width: 80vw;
  }
  .form-card {
    margin: 2em auto 1em;
    width: 90vw;
  }
}
</style>
