<template>
  <div>
    <v-layout class="section darken" row wrap>
      <v-flex lg12 md12 sm12 xs12>
        <v-layout row wrap class="mt-5">
          <v-flex lg12 md12 xs12 sm12>
            <h2
              class="mywhiteText display-2 text-lg-center text-md-center mt-5 text-xs-center"
            >CONTACT US</h2>
            <div class="form">
              <v-form v-model="valid" ref="form">
                <v-layout row wrap>
                  <v-text-field
                    dark
                    background-color="transparent"
                    color="green"
                    box
                    v-model="name"
                    :rules="nameRules"
                    :counter="30"
                    label="Name"
                    class="my-input"
                    required
                  ></v-text-field>
                </v-layout>

                <v-layout row wrap>
                  <v-text-field
                    dark
                    color="green"
                    background-color="transparent"
                    v-model="email"
                    :rules="emailRules"
                    :counter="50"
                    box
                    label="E-mail"
                    class="my-input"
                    required
                  ></v-text-field>
                </v-layout>

                <v-layout row wrap>
                  <v-text-field
                    height="6em"
                    dark
                    color="green"
                    box
                    background-color="transparent"
                    v-model="message"
                    label="Message"
                    class="my-input"
                    required
                  ></v-text-field>
                </v-layout>
                <v-alert v-if="alert" :value="true" class="myalert" type="success">Email sent</v-alert>
                <v-layout row wrap justify-space-around>
                  <v-btn
                    large
                    flat
                    :disabled="!valid"
                    color="#2CC804"
                    @click="validate"
                    class="myBtn"
                  >Send</v-btn>
                </v-layout>
              </v-form>
            </div>
          </v-flex>
          <v-flex lg12 md12 xs12 sm12>
            <v-layout class="socialIcons" justify-space-around>
              <v-icon router to="http://facebook.com/forthotel" color="white">fab fa-facebook</v-icon>
              <v-icon router to="http://youtube.com/forthotel" color="white">fab fa-youtube</v-icon>
              <v-icon router to="http://twitter.com/forthotel" color="white">fab fa-twitter</v-icon>
              <v-icon router to="#" color="white">fab fa-whatsapp</v-icon>
            </v-layout>
          </v-flex>
        </v-layout>
      </v-flex>
      <v-flex lg12 md12 xs12 sm12>
        <v-layout class="copyText" justify-space-around>
          <p>&copy; 2019 Fort Hotel</p>
        </v-layout>
      </v-flex>
    </v-layout>
  </div>
</template>
<script>
import { APIService } from "../Api";
const apiService = new APIService();

export default {
  name: "AppFooter",
  data() {
    return {
      valid: false,
      alert: false,
      name: "",
      nameRules: [
        v => !!v || "Name is required",
        v => v.length <= 50 || "Name must be less than 50 characters"
      ],
      message: "",
      email: "",
      emailRules: [
        v => !!v || "E-mail is required",
        v => /.+@.+/.test(v) || "E-mail must be valid"
      ]
    };
  },
  methods: {
    clear() {
      this.name = "";
      this.email = "";
      this.message = "";
    },
    validate() {
      let mail_subject = "Contact Information";
      let mail_body =
        "<p>" +
        " Name: " +
        this.name +
        "</p>" +
        "<p>" +
        " Email: " +
        this.email +
        "</p>" +
        "<p>" +
        " Message: " +
        this.message +
        "</p>";
      apiService.sendContactEmail(mail_subject, mail_body);
      this.alert = true;
      this.$refs.form.reset();
    }
  }
};
</script>
<style scoped>
@import "../assets/css/style.css";

.form,
.socialIcons,
.copyText {
  width: 30vw;
  margin: 1em auto;
}

.copyText {
  margin-top: 1em;
  color: white;
}

.my-input.v-input .v-input__slot {
  border-radius: 0px;
}

@media screen and (max-width: 960px) {
  .form {
    width: 80vw;
    margin: 1em auto;
  }
  .myfootertext {
    padding-left: 1em;
  }
  .socialIcons,
  .copyText {
    width: 100vw;
    margin: 1em auto;
  }
}
.myalert {
  width: 100%;
}
</style>
